import { ccf } from '../js/ccf-app/global.js';

function count(request) {
    let counts = ccf.kv["counts"];
    const id = ccf.jsonCompatibleToBuf(request.params.id);
    if (counts.has(id)) {
        return {
            body: {
                count: ccf.bufToJsonCompatible(counts.get(id))
            }
        };
    }
    else {
        return {
            statusCode: 404,
            body: `No count found for ${request.params.id}`
        };
    }
}

export { count };

import { ccf } from '../js/ccf-app/global.js';

function increment(request) {
    let counts = ccf.kv["counts"];
    const id = ccf.jsonCompatibleToBuf(request.params.id);
    const prevCount = counts.has(id) ? ccf.bufToJsonCompatible(counts.get(id)) : 0;
    counts.set(id, ccf.jsonCompatibleToBuf(prevCount + 1));
    return {};
}

export { increment };

